    h, w = len(grid), len(grid[0])
    sep = None
    # horizontal separator row
    for i, r in enumerate(grid):
        if len(set(r)) == 1:
            c = r[0]
            if all(c not in grid[j] for j in range(h) if j != i):
                sep = ('r', i)
                break
    if sep is None:
        for c in range(w):
            col = [grid[i][c] for i in range(h)]
            if len(set(col)) == 1:
                v = col[0]
                if all(grid[i][j] != v for i in range(h) for j in range(w) if j != c):
                    sep = ('c', c)
                    break
    if sep[0] == 'r':
        A, B = grid[:sep[1]], grid[sep[1] + 1:]
    else:
        A = [r[:sep[1]] for r in grid]
        B = [r[sep[1] + 1:] for r in grid]
    cnt = Counter()
    for r in B:
        cnt.update(r)
    v = min(cnt, key=cnt.get)
    return [[3 if (a == v and b == v) else v for a, b in zip(ra, rb)]
            for ra, rb in zip(A, B)]
